package org.slint.material.parity

import org.json.JSONObject

/** One resolved parity scene: `scenes/<name>.json` as generated by
 * `material-parity-generator` (authored fields plus the ARGB `scheme` map and
 * `case_rel`, the reference directory under `references/`). */
class Scene(json: JSONObject) {
    val name: String = json.getString("name")
    val type: String = json.getString("type")
    val parity: String = json.getString("parity")
    val caseRel: String = json.getString("case_rel")
    val sizeDp: Pair<Int, Int> =
        json.getJSONArray("size").let { it.getInt(0) to it.getInt(1) }
    val densities: List<Int> =
        json.getJSONArray("densities").let { a -> (0 until a.length()).map(a::getInt) }
    val times: List<Long> =
        json.optJSONArray("times")?.let { a -> (0 until a.length()).map(a::getLong) }
            ?: emptyList()
    val traceProps: List<String> = stringList(json, "trace_props")
    val traceElements: List<String> = stringList(json, "trace_elements")
    val actions: List<Action> =
        json.optJSONArray("actions")?.let { a -> (0 until a.length()).map { Action(a.getJSONObject(it)) } }
            ?: emptyList()
    val widgets: List<Widget> =
        json.optJSONArray("widgets")?.let { a -> (0 until a.length()).map { Widget(a.getJSONObject(it)) } }
            ?: emptyList()
    val params: JSONObject = json.optJSONObject("params") ?: JSONObject()
    /** Authored theme inputs (seed/variant/spec/platform/dark/contrast) that
     * both scheme derivations consume. */
    val theme: JSONObject = json.optJSONObject("theme") ?: JSONObject()
    val scheme: Map<String, Long> =
        json.getJSONObject("scheme").let { s ->
            s.keys().asSequence().associateWith { s.getString(it).toLong(16) }
        }

    private fun stringList(json: JSONObject, key: String): List<String> =
        json.optJSONArray(key)?.let { a -> (0 until a.length()).map(a::getString) } ?: emptyList()

    /** Loads every scene named by the generated `scenes/index.txt` resource. */
    companion object {
        fun loadAll(): List<Scene> {
            val loader = Scene::class.java.classLoader
            return loader.getResourceAsStream("scenes/index.txt")!!.bufferedReader()
                .readLines()
                .filter { it.isNotBlank() }
                .map { name ->
                    Scene(JSONObject(loader.getResourceAsStream("scenes/$name.json")!!.bufferedReader().readText()))
                }
        }
    }
}

class Action(json: JSONObject) {
    val kind: String = json.getString("kind")
    val x: Float = json.getDouble("x").toFloat()
    val y: Float = json.getDouble("y").toFloat()
    /** Dispatch time within the frame sequence (ms); `0` fires right after
     * the pre-gesture baseline frame, as before. */
    val at: Long = json.optLong("at", 0)
}

class Widget(json: JSONObject) {
    val kind: String = json.getString("kind")
    val x: Float = json.optDouble("x", 0.0).toFloat()
    val y: Float = json.optDouble("y", 0.0).toFloat()
    val width: Float = json.optDouble("width", 0.0).toFloat()
    val height: Float = json.optDouble("height", 0.0).toFloat()
    val radius: Float = json.optDouble("radius", 0.0).toFloat()
    val text: String? = (json.opt("text") as? String)?.takeIf { it.isNotEmpty() }
    /** Stem of an svg under `src/ui/icons/` (`check` → `icons/check.svg`),
     * loaded as an [ImageVector] — the same path the Slint `Icons` image
     * rasterizes. */
    val icon: String? = (json.opt("icon") as? String)?.takeIf { it.isNotEmpty() }
    /** `connected-button`/`GroupItem.checked_icon`: swaps `icon` while the
     * item is checked (the upstream samples' filled/outlined swap). */
    val checkedIcon: String? = (json.opt("checked_icon") as? String)?.takeIf { it.isNotEmpty() }
    val enabled: Boolean = json.optBoolean("enabled", true)
    /** Interaction state the widget starts in: `enabled` (default),
     * `disabled`, `pressed` (pointer held), `hovered`, or `focused`. */
    val state: String = (json.opt("state") as? String)
        ?: (if (json.optBoolean("enabled", true)) "enabled" else "disabled")
    val color: String? = (json.opt("color") as? String)?.takeIf { it.isNotEmpty() }
    /** Button size bucket `xs`/`s`/`m`/`l`/`xl` — maps to the container
     * heights and [ToggleButtonSize]s; `s` is the upstream default. */
    val size: String = (json.opt("size") as? String) ?: "s"
    /** Button container corners: `round` (default stadium) or `square`. */
    val corner: String = (json.opt("corner") as? String) ?: "round"
    /** M3 elevation level (0–5) for `surface` widgets, mapped to
     * `Modifier.shadow`'s dp by `elevationDp`. */
    val level: Int = json.optInt("level", 0)
    /** Caster outline for `surface` widgets: a `MaterialShapes` member name
     * in kebab case (`"cookie-9-sided"` → `MaterialShapes.Cookie9Sided`), or
     * `"rect"` (default) for `radius`'s rounded rectangle. */
    val shape: String =
        if (json.isNull("shape")) "rect" else json.getString("shape")
    /** Toggle variant (`checkable` on the Slint side, `*ToggleButton`
     * composables upstream). */
    val checkable: Boolean = json.optBoolean("checkable", false)
    val checked: Boolean = json.optBoolean("checked", false)
    /** Icon-button container width `narrow`/`uniform`/`wide`. */
    val widthOption: String = (json.opt("width_option") as? String) ?: "uniform"
    /** Loading-indicator mode: indeterminate (the continuous morph loop,
     * default) or driven by [progress]. */
    val indeterminate: Boolean = json.optBoolean("indeterminate", true)
    /** Determinate loading-indicator progress, 0–1. */
    val progress: Float = json.optDouble("progress", 0.0).toFloat()
    /** `top-app-bar` variant: `small` (default), `center`, `medium`,
     * `medium-flexible`, `large`, `large-flexible`, `two-rows`. */
    val variant: String = (json.opt("variant") as? String) ?: "small"
    val subtitle: String? = (json.opt("subtitle") as? String)?.takeIf { it.isNotEmpty() }
    /** `TopAppBarState.heightOffset`/`BottomAppBarState.heightOffset` —
     * negative values render a partially collapsed bar. */
    val heightOffset: Float = json.optDouble("height_offset", 0.0).toFloat()
    /** `TopAppBarState.contentOffset` — positive values mark the content
     * overlapped, flipping the single-row bar to its scrolled color. */
    val contentOffset: Float = json.optDouble("content_offset", 0.0).toFloat()
    val navIcon: String? = (json.opt("nav_icon") as? String)?.takeIf { it.isNotEmpty() }
    /** `top-app-bar` action / `bottom-app-bar` icon-button icon stems. */
    val icons: List<String> =
        json.optJSONArray("icons")?.let { a -> (0 until a.length()).map(a::getString) } ?: emptyList()
    val placeholder: String? = (json.opt("placeholder") as? String)?.takeIf { it.isNotEmpty() }
    /** `*-split-button` kinds only: which half carries `state` and receives
     * the scripted pointer gesture — `leading` or `trailing`. */
    val side: String = (json.opt("side") as? String) ?: "trailing"
    /** `*-split-button` trailing icon stem — `keyboard_arrow_down`, the
     * chevron the upstream samples rotate, when unset — and the standalone
     * `menu-item` widget's trailing icon. */
    val trailingIcon: String? = (json.opt("trailing_icon") as? String)?.takeIf { it.isNotEmpty() }
    /** `connected-button` only: `start`/`middle`/`end` — the position's
     * `connected*ButtonShapes`. `start` is the leading item of a horizontal
     * group, the top item of a vertical one. */
    val position: String = (json.opt("position") as? String) ?: "middle"
    /** `connected-button` only: the `VerticalButtonGroupSample` shapes —
     * `CornerSize(100)` caps on `start`/`end`, uniform 6dp pressed. */
    val vertical: Boolean = json.optBoolean("vertical", false)
    /** `connected-button-group`/`vertical-connected-button-group` items. */
    val items: List<GroupItem> =
        json.optJSONArray("items")?.let { a -> (0 until a.length()).map { GroupItem(a.getJSONObject(it)) } }
            ?: emptyList()
    /** Groups: every item carries its own checked state instead of one
     * [selectedIndex]. */
    val multiSelect: Boolean = json.optBoolean("multi_select", false)
    /** Single-select groups: the checked item (`-1` selects none). */
    val selectedIndex: Int = json.optInt("selected_index", -1)
    /** `extended-fab` expansion state (`expanded` upstream). */
    val expanded: Boolean = json.optBoolean("expanded", true)
    /** `fab`/`extended-fab` visibility — `visible` on
     * `Modifier.animateFloatingActionButton` upstream. */
    val shown: Boolean = json.optBoolean("shown", true)
    /** `animateFloatingActionButton` scale pivot — `Alignment` member name
     * in snake case (`bottom_end` default). */
    val alignment: String = (json.opt("alignment") as? String) ?: "bottom_end"
    /** `animateFloatingActionButton` `targetScale` (0.2 upstream). */
    val targetScale: Float = json.optDouble("target_scale", 0.2).toFloat()
    /** The prop a press+release click toggles — `expanded` or `shown`. */
    val toggle: String? = (json.opt("toggle") as? String)?.takeIf { it.isNotEmpty() }
    /** `extended-fab` label-slot width pin — `Modifier.width` on the
     * upstream `text` composable; 0/unset sizes it to the text. */
    val labelWidth: Float = json.optDouble("label_width", 0.0).toFloat()
    /** `*-divider` line thickness in dp — `DividerDefaults.Thickness` when
     * unset; `0` is the upstream `Dp.Hairline` (one physical pixel). */
    val thickness: Float = json.optDouble("thickness", 1.0).toFloat()

    val isFab: Boolean get() = kind == "fab" || kind == "extended-fab"
    val isSplitButton: Boolean get() = kind.endsWith("split-button")
    val isIconButton: Boolean get() = kind.endsWith("icon-button")
    val isButton: Boolean get() =
        (isIconButton || isSplitButton || kind.endsWith("-button")) && kind != "connected-button"
    /** `elevated-rect` only: the elevation in dp of the Android ambient+spot
     * shadow `Modifier.shadow` draws behind the caster. */
    val elevation: Float = json.optDouble("elevation", 0.0).toFloat()

    // ---- menu family -------------------------------------------------

    /** Menu item kind: `standard` (default), `selectable`, `checkable`. */
    val itemKind: String = (json.opt("item_kind") as? String) ?: "standard"
    /** `menu`/`menu-popup`/`menu-group` item models. `menu_items` so the
     * key doesn't shadow `connected-button-group`'s typed `items`. */
    val menuItems: List<MenuItem> =
        json.optJSONArray("menu_items")?.let { a -> (0 until a.length()).map { MenuItem(a.getJSONObject(it)) } }
            ?: emptyList()
    /** `menu-popup` group models. */
    val groups: List<MenuGroup> =
        json.optJSONArray("groups")?.let { a -> (0 until a.length()).map { MenuGroup(a.getJSONObject(it)) } }
            ?: emptyList()
    /** `menu-item`/`menu-group` shape position: `standalone` (default),
     * `leading`, `middle`, `trailing`. `shape_position` so the key doesn't
     * shadow `connected-button`'s `position`. */
    val shapePosition: String = (json.opt("shape_position") as? String) ?: "standalone"
    val selected: Boolean = json.optBoolean("selected", false)
    val selectedIcon: String? = (json.opt("selected_icon") as? String)?.takeIf { it.isNotEmpty() }
    val trailingText: String? = (json.opt("trailing_text") as? String)?.takeIf { it.isNotEmpty() }
    val supportingText: String? = (json.opt("supporting_text") as? String)?.takeIf { it.isNotEmpty() }
    /** `menu-group`/`menu-group-label` label text. */
    val label: String? = (json.opt("label") as? String)?.takeIf { it.isNotEmpty() }
    /** `menu` only: hide the leading `first-index` items. */
    val firstIndex: Int = json.optInt("first_index", 0)

    val isMenu: Boolean get() =
        kind == "menu" || kind == "menu-popup" || kind == "menu-group" ||
            kind == "menu-item" || kind == "menu-divider" || kind == "menu-group-label"
}

/** One entry of a menu `items`/`groups[].items` model — the slots of
 * `DropdownMenuItemContent`. */
class MenuItem(json: JSONObject) {
    val text: String = json.optString("text", "")
    val icon: String? = (json.opt("icon") as? String)?.takeIf { it.isNotEmpty() }
    val selectedIcon: String? = (json.opt("selected_icon") as? String)?.takeIf { it.isNotEmpty() }
    val trailingIcon: String? = (json.opt("trailing_icon") as? String)?.takeIf { it.isNotEmpty() }
    val trailingText: String? = (json.opt("trailing_text") as? String)?.takeIf { it.isNotEmpty() }
    val supportingText: String? = (json.opt("supporting_text") as? String)?.takeIf { it.isNotEmpty() }
    val selected: Boolean = json.optBoolean("selected", false)
    val checked: Boolean = json.optBoolean("checked", false)
    val enabled: Boolean = json.optBoolean("enabled", true)
    /** `hovered`/`pressed`/`focused` — emitted on the item's own
     * `InteractionSource`. */
    val state: String? = json.opt("state") as? String
}

/** One entry of a menu `groups` model (`DropdownMenuGroup` + label). */
class MenuGroup(json: JSONObject) {
    val label: String = json.optString("label", "")
    val items: List<MenuItem> =
        json.optJSONArray("items")?.let { a -> (0 until a.length()).map { MenuItem(a.getJSONObject(it)) } }
            ?: emptyList()
}

/** One item of a `connected-button-group`: the label, an optional leading
 * icon, a `checked_icon` swap while checked, `disabled`, `checked`
 * (multi-select), and an interaction `state` emitted on the item's own
 * `InteractionSource`. */
class GroupItem(json: JSONObject) {
    val text: String? = (json.opt("text") as? String)?.takeIf { it.isNotEmpty() }
    val icon: String? = (json.opt("icon") as? String)?.takeIf { it.isNotEmpty() }
    val checkedIcon: String? = (json.opt("checked_icon") as? String)?.takeIf { it.isNotEmpty() }
    val disabled: Boolean = json.optBoolean("disabled", false)
    val checked: Boolean = json.optBoolean("checked", false)
    /** `enabled` (default), `pressed`, `hovered`, or `focused`. */
    val state: String = (json.opt("state") as? String) ?: "enabled"
}

/** "primary-container" → "primaryContainer" for `scheme` map lookups. */
fun String.kebabToCamel(): String =
    split('-').mapIndexed { i, part -> if (i == 0) part else part.replaceFirstChar(Char::uppercaseChar) }
        .joinToString("")
